<script setup lang="ts">
import {ref,watch,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,imageUrl,money} from './api'
import ShopCard from './ShopCard.vue'
import ActionDialog from './ActionDialog.vue'
import VoucherForm from './VoucherForm.vue'
import TypeIcon from './TypeIcon.vue'
const canCreate=ref(false),creating=ref(false),clock=ref<any>({})
const route=useRoute(),router=useRouter(),shops=ref<any[]>([]),types=ref<any[]>([]),detail=ref<any>(null),keyword=ref(''),type=ref<any>(''),sort=ref('score'),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),tab=ref('商品券'),draft=ref<any>(null)
let generation=0
async function load(){const g=++generation;busy.value=true;error.value='';detail.value=null;try{if(route.params.id){const data=await api('/api/catalog/shops/'+route.params.id);if(g===generation)detail.value=data}else{const data=await api('/api/catalog/shops?'+new URLSearchParams({keyword:keyword.value,...(type.value?{typeId:type.value}:{}),sort:sort.value,page:String(page.value)}));if(g===generation){shops.value=data.data||[];total.value=data.total||0}}}catch(e){if(g===generation)error.value=(e as Error).message}finally{if(g===generation)busy.value=false}}
watch(()=>route.params.id,load,{immediate:true})
onMounted(async()=>{try{const [typeData,cap]=await Promise.all([api('/api/catalog/types'),api('/api/catalog/capabilities')]);types.value=typeData.data||[];canCreate.value=cap.can_create_voucher===true;clock.value=cap}catch(e){error.value=(e as Error).message}})
async function buy(c:any){if(busy.value)return;busy.value=true;try{draft.value=await api('/api/catalog/prepare','POST',{shop_id:detail.value.shop.id,voucher_id:c.id})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function ask(){sessionStorage.setItem('xiangkou-handoff',`请帮我看看${detail.value.shop.name}（店铺ID ${detail.value.shop.id}）的优惠券和探店口碑`);await router.push('/chat')}
async function deleteVoucher(v:any){if(!confirm(`确认下架「${v.title}」吗？`))return;busy.value=true;try{await api(`/api/catalog/vouchers/${v.id}`,'DELETE');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page"><div v-if="error" class="error" role="alert">{{error}}</div><template v-if="!route.params.id"><div class="eyebrow">EXPLORE THE CITY</div><h2>发现下一家心仪的店</h2><p class="muted">从店铺开始，也可以让 巷口 帮你一起挑。</p><form class="filters" @submit.prevent="page=1;load()"><input v-model="keyword" maxlength="50" placeholder="搜索店铺、火锅、KTV…" aria-label="搜索店铺"><select v-model="sort" aria-label="排序"><option value="score">评分优先</option><option value="price">价格优先</option></select><button class="primary" :disabled="busy">搜索</button></form><div class="type-grid" role="group" aria-label="店铺分类"><button type="button" :class="['type-chip',{active:type===''}]" @click="type='';page=1;load()"><TypeIcon :id="null"/><span>全部</span></button><button type="button" v-for="t in types" :key="t.id" :class="['type-chip',{active:String(type)===String(t.id)}]" @click="type=t.id;page=1;load()"><TypeIcon :id="t.id"/><span>{{t.name}}</span></button></div><div class="shop-grid"><ShopCard v-for="s in shops" :key="s.id" :shop="s" @detail="router.push('/shops/'+s.id)"/></div><div v-if="!busy&&!shops.length" class="empty">暂无匹配店铺，试试其他关键词。</div><div class="pagination"><button class="outline" :disabled="busy||page===1" @click="page--;load()">上一页</button><span class="muted small">第 {{page}} 页 · 共 {{total}} 家</span><button class="outline" :disabled="busy||page*12>=total" @click="page++;load()">下一页</button></div></template><template v-else-if="detail?.shop"><button class="text-button" @click="router.push('/shops')">← 返回发现店铺</button><div class="shop-hero"><img v-if="imageUrl(detail.shop.images)" :src="imageUrl(detail.shop.images)" alt="店铺图片" @error="($event.target as HTMLImageElement).style.display='none'"><div><div class="eyebrow">SHOP DETAILS</div><h2>{{detail.shop.name}}</h2><p class="muted">{{detail.shop.area}} · {{detail.shop.address}}</p><p>{{detail.shop.score/10}} 分 · 人均 ¥{{detail.shop.avgPrice}}</p><p class="small muted">登记营业时间：{{detail.shop.openHours||'待核实'}}</p><button class="primary" @click="ask">让助手帮我分析</button></div></div><div class="tabs"><button v-for="t in ['商品券','探店笔记','评价']" :class="{active:tab===t}" :key="t" @click="tab=t">{{t}}</button></div><div v-if="tab==='商品券'"><div v-if="canCreate" class="row" style="margin:18px 0"><p class="muted small" style="margin:0">本地演示商品管理</p><button class="outline" :disabled="busy" @click="creating=true">＋ 添加演示代金券</button></div><div class="voucher-row" v-for="v in detail.vouchers" :key="v.id"><div><span class="pill">{{v.type===1?'限时秒杀':'商品券'}}</span><h3>{{v.title}}</h3><p class="muted small">{{v.rules}}</p><p v-if="v.type===1" class="small">{{v.beginTime}} 至 {{v.endTime}} · 剩余 {{v.stock}} 张</p></div><div><div class="price">¥{{money(v.payValue)}} <del>券面 ¥{{money(v.actualValue)}}</del></div><button class="primary" :disabled="busy||v.orderable===false" @click="buy(v)">{{v.orderable===false?'暂不可购买':v.payValue===0?'领取免费券':'购买商品券'}}</button><button v-if="canCreate" class="text-button" :disabled="busy" @click="deleteVoucher(v)">下架</button></div></div><div v-if="!detail.vouchers.length" class="empty">该店暂无商品券。</div></div><div class="blog-grid" v-if="tab==='探店笔记'"><RouterLink v-for="b in detail.blogs" :key="b.id" :to="'/community/'+b.id" class="blog-card"><img v-if="imageUrl(b.images)" :src="imageUrl(b.images)" alt="探店照片" loading="lazy"><div><h3>{{b.title}}</h3><p class="muted small">{{b.content?.slice(0,80)}}</p></div></RouterLink><p v-if="!detail.blogs.length" class="empty">暂无关联探店笔记。</p></div><div v-if="tab==='评价'" class="empty">当前 既有服务 项目尚未实现评价列表接口。你可以先查看真实探店笔记，了解大家的体验。</div></template><p v-if="busy" class="muted">正在加载点评数据…</p></div><VoucherForm v-if="creating&&detail?.shop" :shop="detail.shop" :clock="clock" @close="creating=false" @created="load"/><ActionDialog v-if="draft" :key="draft.action_id" :draft="draft" @close="draft=null"/></template>
